    "إن الفارق بين المربي الحكيم والمنفعل هو أن الأول ينظر إلى ما بعد التوبة، بينما الثاني يحبس نفسه وابنه في لحظة الذنب. حين يعلم ابنك أنك ملاذه الآمن إذا أخطأ، سيأتيك معترفاً تائباً، بدلاً من أن يهرب إلى رفقاء السوء مخفياً زلله."
