    "أيها الإخوة الكرام: من علامات قبول العمل الصالح في رمضان أن تتبعه بالطاعة بعده. إن رب رمضان هو رب سائر الشهور؛ فإذا كنا قد تذوقنا حلاوة القرآن في التراويح، فلماذا نهجر المصحف بعد العيد؟ وإذا كنا قد ذقنا لذة مناجاة السحر في القيام، فلماذا نحرم أنفسنا من ركعتين في جوف الليل طوال العام؟",
    "إن سر الاستمرارية يكمن في الاقتصاد في العبادة؛ قال النبي ﷺ: «أحب الأعمال إلى الله أدومها وإن قل». اختر لنفسك بعد رمضان عبادات يسيرة تثبت عليها: صيام ثلاثة أيام من كل شهر، وصفحة يومية من القرآن بتدبر، وركعة وتر لا تنام إلا وقد أديتها."
