  "content": [
    "كان يا ما كان، في بستان جميل تسكنه طيور ملونة، كان هناك عصفور صغير لطيف اسمه «ريحان». كان ريحان كلما أكل حبة قمح صغيرة، يقف على غصن الشجرة ويقول بصوته العذب: «الحمد لله الذي أطعمني وسقاني».",
    "في يوم من الأيام، سأله صديقه البلبل: «لماذا تشكر في كل مرة حتى لو كانت الحبة صغيرة جداً؟»، فابتسم ريحان وقال: «لأن الله يحب من يشكره، ولأن الحبة الصغيرة تصنع طاقة أطير بها في السماء الجميلة، ولأن بالشكر تدوم النعم!».",
    "تعلمت الطيور من ريحان أن ترى النعم الجميلة في كل مكان: في قطرات الندى، ودفء الشمس، وسلامة الأجنحة. فصارت كلها تردد معاً كل صباح: «الحمد لله رب العالمين»."
  ],
