    "دواء العجب هو أن تتذكر أن أنفاسك ونبضات قلبك وقوتك كلها عارية من الله تعالى، ولولا أن الله شرح صدرك ويسر لك الطاعة لما ركعت ركعة ولا تصدقت بدرهم؛ ﴿وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًا﴾.",
    "ودواء الكبر هو التواضع للخلق، ومخالطة المساكين، وتذكر أصل خلقة الإنسان من طين، ومصيره إلى التراب، ليبقى القلب منكسراً لربه مشفقاً على عباده."
