export const getContentBySlug = (slug: string): Content | undefined => {
  return CONTENT_DATABASE.find((c) => c.slug === slug || c.id === slug);
};

export const getContentById = (id: string): Content | undefined => {
  return CONTENT_DATABASE.find((c) => c.id === id);
};

export const getRelatedContent = (current: Content, limit: number = 4): Content[] => {
  return CONTENT_DATABASE.filter((c) => c.id !== current.id)
    .map((c) => {
      let score = 0;
      if (c.category === current.category) score += 3;
      if (c.contentType === current.contentType) score += 2;
      const commonTags = c.tags.filter((t) => current.tags.includes(t));
      score += commonTags.length * 1.5;
      return { item: c, score };
    })
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((res) => res.item);
};
